    let lua_state = agent.lua_state_agent;
    let boma = agent.boma();
    if VarModule::is_flag(agent.battle_object, vars::eflame::instance::HIT_CANCEL) {
        VarModule::off_flag(agent.battle_object, vars::eflame::instance::HIT_CANCEL);
    }
    else {
        FT_MOTION_RATE_RANGE(agent, 1.0, 14.0, 18.0);
    }
    frame(lua_state, 14.0);
    FT_MOTION_RATE(agent, 1.0);
}

